package com.yjiyun.chatflows.runtime;
import io.agentscope.extensions.model.openai.OpenAIChatModel;
public final class RuntimeGatewayModelSelfTest {public static void main(String[] args){var model=RuntimeApplication.gatewayModel("dashscope:qwen-plus","http://agentteams-higress:8080/v1","consumer-token-at-least-16");if(!(model instanceof OpenAIChatModel openai)||!"qwen-plus".equals(openai.getModelName()))throw new AssertionError("gateway model construction failed");boolean rejected=false;try{RuntimeApplication.gatewayModel("dashscope:qwen-plus","https://dashscope.aliyuncs.com/compatible-mode/v1","consumer-token-at-least-16");}catch(IllegalStateException e){rejected=true;}if(!rejected)throw new AssertionError("direct public model endpoint accepted");System.out.println("[PASS] production runtime model uses Higress OpenAI-compatible route and consumer token");}}
